package api

import (
	_ "embed"
	"net/http"
)

// catalogMeta is generated by scripts/sync_sources.py and copied into this
// package by the sync workflow. It describes the pinned catalog, not the
// current state of any external source, so serving it requires no network.
//
//go:embed catalog_meta.json
var catalogMeta []byte

// catalogMetadata serves version and coverage information without touching
// PostgreSQL or any upstream site. The API stays useful if either is down.
func (h *Handler) catalogMetadata(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	if _, err := w.Write(catalogMeta); err != nil {
		h.log.Error("write catalog metadata", "error", err)
	}
}
